/** One process per fixed scenario. The epoch singleton is never reset within that process. */
import {createHb2Fixture,HB2_SCOPE} from './gradleOwnedCwcHb2Bootstrap.mjs';
export const HB2_CASES=['normal-provider-1','normal-client-1','normal-provider-4','normal-client-4','ordinary-limit','cleanup-limit','failed-entry','cleanup-retry','partial-cleanup','epoch-limit','owner-limit','global-capacity','denial-limit','reentry','init-failure','boundary','authority-expired','authority-revoke','authority-pin-restore','authority-purpose-restore','authority-approval-restore','authority-budget'];
function refused(fn){try{fn();return {rejected:false,primitive:false};}catch(e){return {rejected:true,primitive:typeof e==='string'};}}
async function refusedAsync(fn){try{await fn();return false;}catch{return true;}}
const snapshot=(f,h)=>({owner:f.owner,ledger:f.ledger(),core:f.diagnostic?.inspect(h)??null});
export async function hb2Case(mode,id){if(!HB2_CASES.includes(id))throw 'hb2_case';const witnesses=[],make=async(cap=1,kind='diagnostic')=>{const f=await createHb2Fixture(mode,cap,kind);witnesses.push(f.witness);return f;};let result;
 if(id.startsWith('normal-')){const [,actor,n]=id.split('-'),capacity=Number(n),trials=[];for(const kind of ['candidate','diagnostic']){const f=await make(capacity,kind),r=f.reader,h=r.beginRead(actor),peers=Array.from({length:capacity-1},()=>r.beginRead(actor)),full=refused(()=>r.beginRead());r.openAttempt(h);const w=r.window(h,'first'),borrow=r.beginBorrow(h,w),transport=r.beginTransport(h,w);r.publish(h,w);r.closeWindow(h,w);if(actor==='client'){const s=r.window(h,'seal');r.publish(h,s);r.closeWindow(h,s);}r.openAttempt(h);const next=r.window(h,'first');r.publish(h,next);r.closeWindow(h,next);if(actor==='client'){const s=r.window(h,'seal');r.publish(h,s);r.closeWindow(h,s);}r.closeRead(h);const held=snapshot(f,h),early=refused(()=>r.reclaim(h));r.endBorrow(h,borrow);const stillTransport=snapshot(f,h),earlyTransport=refused(()=>r.reclaim(h));r.endTransport(h,transport);r.reclaim(h);const drained=snapshot(f,h),late=refused(()=>r.publish(h,w));const fresh=r.beginRead(actor),distinct=fresh!==h;r.closeRead(fresh);r.reclaim(fresh);for(const p of peers){r.closeRead(p);r.reclaim(p);}trials.push({kind,full,early,earlyTransport,late,distinct,held,stillTransport,drained,final:snapshot(f)});}result={actor,capacity,trials};
 }else if(id==='ordinary-limit'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first'),b=r.beginBorrow(h,w),t=r.beginTransport(h,w);for(let i=0;i<235;i++)r.window(h,'first');const before=snapshot(f,h),blocked=refused(()=>r.window(h,'first')),after=snapshot(f,h);r.endBorrow(h,b);r.endTransport(h,t);r.reclaim(h);result={before,blocked,after,final:snapshot(f)};
 }else if(id==='cleanup-limit'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first');r.beginBorrow(h,w);r.closeRead(h);const failures=[];for(let i=0;i<15;i++)failures.push(refused(()=>r.reclaim(h)));const before=snapshot(f,h),blocked=refused(()=>r.reclaim(h)),retry=refused(()=>r.reclaim(h));result={failures,before,blocked,retry,final:snapshot(f,h)};
 }else if(id==='failed-entry'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first'),before=snapshot(f,h),failed=refused(()=>r.publish(h,Object.freeze(Object.create(null)))),after=snapshot(f,h),retry=refused(()=>r.publish(h,w)),retried=snapshot(f,h);r.reclaim(h);result={before,failed,after,retry,retried,final:snapshot(f)};
 }else if(id==='cleanup-retry'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const b=r.beginBorrow(h,r.window(h,'first'));r.closeRead(h);const first=refused(()=>r.reclaim(h)),one=snapshot(f,h),second=refused(()=>r.reclaim(h)),two=snapshot(f,h);r.endBorrow(h,b);r.reclaim(h);result={first,one,second,two,final:snapshot(f)};
 }else if(id==='partial-cleanup'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);r.closeRead(h);f.diagnostic.arm('cleanup-after-first');const failed=refused(()=>r.reclaim(h)),partial=snapshot(f,h);r.reclaim(h);result={failed,partial,final:snapshot(f)};
 }else if(id==='epoch-limit'){const f=await make(),r=f.reader;for(let i=0;i<64;i++){const h=r.beginRead();r.closeRead(h);r.reclaim(h);}const before=snapshot(f),blocked=refused(()=>r.beginRead()),after=snapshot(f),fresh=await make(),newOwner=refused(()=>fresh.reader.beginRead());const reloaded=await import('./gradleOwnedCwcHb2Bootstrap.mjs?hb2-reload');const again=await reloaded.createHb2Fixture(mode,1,'diagnostic');witnesses.push(again.witness);const reloadedOwner=refused(()=>again.reader.beginRead());result={before,blocked,after,newOwner,reloadedOwner,sameEpoch:f.epochKey===fresh.epochKey&&f.epochKey===again.epochKey,final:snapshot(f)};
 }else if(id==='owner-limit'){const all=[];for(let i=0;i<4;i++)all.push(await make());const handles=all.map(f=>f.reader.beginRead()),before=snapshot(all[0]);for(let i=0;i<4;i++){all[i].reader.closeRead(handles[i]);all[i].reader.reclaim(handles[i]);}const blocked=await refusedAsync(()=>make());result={before,blocked,sameEpoch:all.every(f=>f.epochKey===all[0].epochKey),final:snapshot(all[0])};
 }else if(id==='global-capacity'){const a=await make(4),b=await make(4),reads=[a.reader.beginRead(),a.reader.beginRead(),a.reader.beginRead()],peer=b.reader.beginRead(),before=snapshot(b,peer),blocked=refused(()=>b.reader.beginRead()),after=snapshot(b,peer);for(const h of reads){a.reader.closeRead(h);a.reader.reclaim(h);}b.reader.closeRead(peer);b.reader.reclaim(peer);const drained=snapshot(b),next=b.reader.beginRead();b.reader.closeRead(next);b.reader.reclaim(next);result={sameEpoch:a.epochKey===b.epochKey,before,blocked,after,drained,final:snapshot(b)};
 }else if(id==='denial-limit'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first'),b=r.beginBorrow(h,w),t=r.beginTransport(h,w),before=snapshot(f,h),denials=[];for(let i=0;i<64;i++)denials.push(refused(()=>r.openAttempt(undefined)));const saturated=snapshot(f,h),blocked=refused(()=>r.window(h,'first'));for(let i=0;i<8;i++)refused(()=>r.openAttempt(undefined));const after=snapshot(f,h),failedCleanup=refused(()=>r.reclaim(h)),failureState=snapshot(f,h);r.endBorrow(h,b);r.endTransport(h,t);r.reclaim(h);const newOwner=await refusedAsync(()=>make());result={before,denials,saturated,blocked,after,failedCleanup,failureState,newOwner,final:snapshot(f)};
 }else if(id==='reentry'){const f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first');f.diagnostic.arm('reenter-publish');const failed=refused(()=>r.publish(h,w)),after=snapshot(f,h);r.reclaim(h);result={failed,after,final:snapshot(f)};
 }else if(id==='init-failure'){const f=await make();f.controller.revoke();const before=snapshot(f),failed=refused(()=>f.reader.beginRead()),after=snapshot(f),invalid=refused(()=>f.reader.reclaim(undefined));result={before,failed,after,invalid,final:snapshot(f)};
 }else if(id==='boundary'){const f=await make(),other=await make(),r=f.reader,h=r.beginRead(),peer=other.reader.beginRead(),before=snapshot(f,h),foreign=refused(()=>r.openAttempt(peer)),empty=refused(()=>r.openAttempt(undefined)),after=snapshot(f,h),attack={};
  for(const name of ['hb2:epoch-owner','hb2:bootstrap','hb2:admission-code','hb2:injected-reader','hb1:diagnostic-control'])attack[name]=await refusedAsync(()=>f.consumer(`import '${name}';export const result=true;`));
  const sealed=await f.consumer("import {reader} from 'hb2:reader';export const result=Object.getPrototypeOf(reader)===null&&Object.keys(reader).length===12&&Object.keys(reader).every(k=>Object.getPrototypeOf(reader[k])===null&&reader[k].constructor===undefined)&&reader.admission===undefined&&reader.resetEpoch===undefined;");
  const errorSealed=await f.consumer("let ok=false;try{await import('hb2:epoch-owner');}catch(e){ok=typeof e==='string';try{e.constructor.constructor('return process')();ok=false;}catch{}}export const result=ok;");
  const options=await refusedAsync(()=>createHb2Fixture(mode,1,'candidate',{ordinary:0}));r.closeRead(h);r.reclaim(h);other.reader.closeRead(peer);other.reader.reclaim(peer);result={before,foreign,empty,after,attack,sealed,errorSealed,options,resetAbsent:f.controller.resetEpoch===undefined,final:snapshot(f)};
 }else{const how=id.slice('authority-'.length),f=await make(),r=f.reader,h=r.beginRead();r.openAttempt(h);const w=r.window(h,'first');if(how==='expired')f.controller.advance(4500);else if(how==='revoke')f.controller.revoke();else if(how==='pin-restore'){f.controller.setPin(2);f.controller.setPin(1);}else if(how==='purpose-restore'){f.controller.setPurpose('other');f.controller.setPurpose('read');}else if(how==='approval-restore'){f.controller.setApproval(false);f.controller.setApproval(true);}else f.controller.setBudget(0,0);const before=snapshot(f,h),failed=refused(()=>r.publish(h,w)),after=snapshot(f,h),retry=refused(()=>r.publish(h,w));r.reclaim(h);result={how,before,failed,after,retry,final:snapshot(f)};}
 return {id:`${mode}/${id}`,mode,scenario:id,result,witnesses,scope:HB2_SCOPE};
}
